"""Inspect original bolted-flange CAD/RST and gear-pump reference figures. No solves."""
from pathlib import Path
import json,hashlib,re,zipfile
import numpy as np,h5py
from ansys.mapdl import reader
D=Path('cvpr2027/data');R=D/'web-cad-fem-flange-contact';T=Path('cvpr2027/tmp/cad-fem-machinery-search')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def cad_audit(p):
 with h5py.File(p) as h:
  rows={k:{'shape':list(h[k].shape),'bytes':h[k].size*h[k].dtype.itemsize,'sha256':hashlib.sha256(np.asarray(h[k]).tobytes()).hexdigest()} for k in h if isinstance(h[k],h5py.Dataset)}
 assert rows.get('AGP Parasolid Data',{}).get('bytes',0)>10000
 return {'path':str(p.relative_to(R)),'sha256':sha(p),'native_format':'Ansys DesignModeler HDF5, serialized Parasolid','datasets':rows,'independent_brep_import':False}
records=[]
selected=[('spsvision',R/'spsvision/boltedFlange_files/dp0/SYS/MECH/file.rst')]
selected.append(('saturn-nozzle',next((R/'saturn-nozzle/extracted-original').rglob('*.rst'))))
selected.extend(('sornanathan-'+p.parent.parent.name,p) for p in sorted((R/'sornanathan/extracted-original').rglob('*.rst')))
for case,p in selected:
 r=reader.read_binary(p);inp=p.parent/'ds.dat';text=inp.read_text(errors='replace');assert '/units,BIN' in text;assert 'antype,0' in text
 sc=p.parent.parent/'DM'/f'{p.parent.parent.name}.agdb';native=cad_audit(sc);units={'length':'inch','stress':'psi','temperature':'degF','force':'lbf','from':'/units,BIN and source input comments'};states=[]
 outdir=R/'saved-fields'/case;outdir.mkdir(parents=True,exist_ok=True)
 for i,label in enumerate(r.time_values):
  ids,u=r.nodal_displacement(i);sid,s=r.nodal_stress(i);tid,temp=r.nodal_temperature(i);assert np.array_equal(ids,sid) and np.array_equal(ids,tid) and np.array_equal(ids,r.mesh.nnum);assert np.isfinite(u).all();mask=np.isfinite(s).all(1);a=s[mask];vm=np.sqrt(.5*((a[:,0]-a[:,1])**2+(a[:,1]-a[:,2])**2+(a[:,2]-a[:,0])**2)+3*(a[:,3]**2+a[:,4]**2+a[:,5]**2));out=outdir/f'state-{i}.npz';np.savez_compressed(out,node_ids=ids,mesh_coordinates=r.mesh.nodes,displacement=u,recovered_nodal_stress=s,nodal_temperature=temp,finite_stress_mask=mask)
  with np.load(out) as z:
   assert np.array_equal(z['displacement'],u,equal_nan=True) and np.array_equal(z['recovered_nodal_stress'],s,equal_nan=True) and np.array_equal(z['nodal_temperature'],temp,equal_nan=True)
  finite_temp=temp[np.isfinite(temp)]
  states.append({'reader_index':i,'static_stage_label':float(label),'maximum_translation_inch':float(np.linalg.norm(u[:,:3],axis=1).max()),'finite_recovered_peak_vm_psi':float(vm.max()),'finite_stress_rows':int(mask.sum()),'missing_stress_rows':int((~mask).sum()),'finite_temperature_range_degF':[float(finite_temp.min()),float(finite_temp.max())] if len(finite_temp) else None,'npz':str(out.relative_to(R)),'npz_sha256':sha(out)})
 mat=(p.parent/'MatML.xml').read_text();names=re.findall(r'<Name>(.*?)</Name>',mat);materials=[x for x in names if x in ['Structural Steel','Stainless Steel','Inconel 718','AISI 304'] or ('Steel'in x)]
 metadata_folder=R/('sornanathan' if case.startswith('sornanathan') else case);m=json.loads((metadata_folder/'download-manifest.json').read_text());log=(p.parent/'solve.out').read_text(errors='replace') if (p.parent/'solve.out').exists() else '';count=re.findall(r'NUMBER OF\s+(WARNING|ERROR)\s+MESSAGES ENCOUNTERED=\s*(\d+)',log)
 rec={'id':case,'source':m['source'],'revision':m['revision'],'raw_rst':str(p.relative_to(R)),'rst_sha256':sha(p),'input':str(inp.relative_to(R)),'input_sha256':sha(inp),'native_cad':native,'mesh_nodes':r.mesh.n_node,'mesh_elements':r.mesh.n_elem,'mesh_bbox_inch':[r.mesh.nodes.min(0).tolist(),r.mesh.nodes.max(0).tolist()],'states':states,'units':units,'source_material_names':sorted(set(materials)),'source_log_message_counts':count,'source_log_completed':('RUN COMPLETED'in log),'analysis_type':'Static nonlinear/contact stages with imposed thermal body load, antype,0. Stage labels do not establish physical transient time.','certified_cases':0}
 records.append(rec);print(case,r.mesh.n_node,r.mesh.n_elem,len(states),states[-1]['maximum_translation_inch'],states[-1]['finite_recovered_peak_vm_psi'],flush=True)
cat={'collection':'Published bolted nozzle-flange sector CAD and static contact/thermal-expansion FEM','date':'2026-10-12','engineering_families':1,'source_repositories':3,'native_cad_raw_solution_candidates':len(records),'unique_original_rst_hashes':len(set(x['rst_sha256'] for x in records)),'saved_state_count':sum(len(x['states']) for x in records),'records':records,'certified_cases':0,'frontier_model_calls':0,'solver_runs':0,'locally_generated_cad':0,'independent_brep_verified_pairs':0,'original_dimensioned_engineering_drawings_verified':0,'reader':'ansys-mapdl-reader 0.56.0','stress_recovery':'nodal_stress averages element-nodal stresses at shared corner nodes; finite rows only; NaN masks retained. Components X,Y,Z,XY,YZ,XZ.','limitations':['Three publisher sources grouped as one sector-flange geometry family. Saved setups/results differ; physical independence and tutorial provenance require review.','Native AGDB has nonempty serialized Parasolid data. No original neutral STEP or independent BREP import completed.','Source static stages are not validated transient rocket-launch responses. No independent heat-conduction result file found.','Saturn-nozzle README claims Inconel 718 bolts, 500 C, SI pressure values, different mesh counts and 2.31 mm displacement. Saved input instead uses /units,BIN, steel/stainless materials, 70 to700 F and static stages. Exact README/source discrepancies must not be relabeled as ground truth.','Stress peaks can exceed source linear-elastic strength and may be dominated by local contact/mesh singularities; no failure certificate claimed.','Need full CAD/result correspondence, contact/pretension review, convergence and reference recovery convention before admission.','spsvision and Sornanathan licenses unresolved; Saturn repository MIT notice retained. Local research only, no public release.']};(R/'catalog.json').write_text(json.dumps(cat,indent=2)+'\n')
# Confirm the standalone Saturn result is an unchanged duplicate of the archive member.
p=R/'saturn-nozzle/FEA_Simulations/SaturnV_F1_SimulationResults.rst';q=next((R/'saturn-nozzle/extracted-original').rglob('*.rst'));assert sha(p)==sha(q)
print('Saturn standalone/archive RST duplicate verified',flush=True)
